use codeint_model::language::SourceSet;
use codeint_model::{has_any_ascii_marker, has_folder_named};

#[cfg(test)]
mod tests;

const GENERATED_SUFFIXES: [&str; 8] = [
    ".g.dart",
    ".freezed.dart",
    ".gr.dart",
    ".mocks.dart",
    ".pb.dart",
    ".pbenum.dart",
    ".pbjson.dart",
    ".pbserver.dart",
];

const GENERATED_MARKERS: [&str; 6] = [
    "generated code",
    "@generated",
    "do not edit",
    "do not modify by hand",
    "auto-generated",
    "autogenerated",
];

const TEST_FOLDERS: [&str; 3] = ["test", "tests", "integration_test"];
const WORKSPACE_CONTAINERS: [&str; 8] = [
    "packages",
    "pkgs",
    "apps",
    "libs",
    "modules",
    "crates",
    "services",
    "workspaces",
];

pub(crate) fn classify(path: &str, header_comments: &str) -> SourceSet {
    if is_generated(path, header_comments) {
        return SourceSet::Generated;
    }
    if is_test_path(path) {
        return SourceSet::Test;
    }
    SourceSet::Production
}

pub(crate) fn is_tooling_file(path: &str) -> bool {
    let Some((dir, _)) = path.rsplit_once('/') else {
        return false;
    };
    let segments: Vec<&str> = dir.split('/').collect();
    for (index, segment) in segments.iter().enumerate() {
        if segment.eq_ignore_ascii_case("lib") {
            return false;
        }
        if is_dart_tooling_segment(&segments, index) {
            return true;
        }
    }
    false
}

fn is_dart_tooling_segment(segments: &[&str], index: usize) -> bool {
    let Some(segment) = segments.get(index) else {
        return false;
    };
    let is_tool = segment.eq_ignore_ascii_case("tool");
    let is_example = segment.eq_ignore_ascii_case("example");
    if !is_tool && !is_example {
        return false;
    }
    if is_tool
        && segments
            .get(index + 1)
            .is_some_and(|next| next.eq_ignore_ascii_case("lib"))
    {
        return false;
    }
    let Some(parent) = index.checked_sub(1).and_then(|prev| segments.get(prev)) else {
        return true;
    };
    !WORKSPACE_CONTAINERS
        .iter()
        .any(|container| parent.eq_ignore_ascii_case(container))
}

fn is_generated(path: &str, header_comments: &str) -> bool {
    GENERATED_SUFFIXES
        .iter()
        .any(|suffix| path.ends_with(suffix))
        || has_any_ascii_marker(header_comments, &GENERATED_MARKERS)
}

fn is_test_path(path: &str) -> bool {
    path.ends_with("_test.dart") || has_folder_named(path, &TEST_FOLDERS)
}
